function checkShelves(shelf, deps) {
  const problems = [];
  for (const [name, uses] of Object.entries(deps)) {
    for (const used of uses) {
      if (shelf[used] >= shelf[name]) problems.push(`${name} may not use ${used}`);
    }
  }
  return problems;
}

const shelf = { errors: 0, schema: 1, config: 1, runtime: 2, http: 3 };
const deps = {
  errors: [],
  schema: ["errors"],
  config: ["errors", "schema"],
  runtime: ["config", "errors"],
  http: ["runtime", "errors"],
};
console.log(checkShelves(shelf, deps));
console.log(checkShelves(shelf, { ...deps, errors: ["http"] }));

