import { schema } from "@zudojs/schema";

const NewBookSchema = schema.object({
  title: schema.string().trim().min(1),
  priceCents: schema.number().int().min(0),
});

function createBook(body) {
  const result = NewBookSchema.safeParse(body);
  if (!result.success) {
    return { status: 400, fields: result.issues.map((issue) => issue.path.join(".")) };
  }
  return { status: 201, book: result.data };
}

console.log(JSON.stringify(createBook({ title: " Kindred ", priceCents: 1099 })));
console.log(JSON.stringify(createBook({ title: "", priceCents: -5 })));
